-export function optimizeSplitBunker(input: SplitBunkerInput): SplitBunkerResult {
-  const { route, bunkerPrices, consumptionMtPerDay } = input;
-
-  const routePorts = [route.fromPort, ...route.intermediatePorts, route.toPort];
