+#!/usr/bin/env -S npx tsx
+/**
+ * backfill-last-cargoes.ts — lastCargoes regex backfill for parsed vessel results.
+ *
+ * Old vessel rows parsed before the B9 regex fallback was wired lack lastCargoes
+ * even when the email body contains explicit L/C: markers. This script re-extracts
+ * from email body (emails.body, joined via account_id + gmail_message_id) using
+ * the same regex as the live fallback and patches result_json in-place — all other
+ * fields are untouched.
+ *
+ * Usage:
+ *   npx tsx scripts/demo-seed/backfill-last-cargoes.ts [--db data/demo-seed.db]   # dry (default)
+ *   npx tsx scripts/demo-seed/backfill-last-cargoes.ts --apply                    # write
+ *
+ * Idempotent: items with an existing non-null lastCargoes are skipped;
+ * a second --apply run patches 0 items.
+ */
+
+import Database from 'better-sqlite3';
+import * as fs from 'node:fs';
+import * as path from 'node:path';
+import { extractLastCargoesFromBody } from '../../lib/parsing/lastcargoes-fallback';
+
+function arg(k: string): string | undefined {
+  const i = process.argv.indexOf(k);
+  return i === -1 ? undefined : process.argv[i + 1];
+}
+
+const APPLY = process.argv.includes('--apply');
+const DB_PATH = arg('--db') ?? path.resolve(process.cwd(), 'data/demo-seed.db');
+
+function main(): void {
+  console.log(`[backfill-last-cargoes] db=${DB_PATH}${APPLY ? ' (APPLY)' : ' (DRY)'}`);
+
+  if (!fs.existsSync(DB_PATH)) {
+    console.error(`[backfill-last-cargoes] ERROR: db not found: ${DB_PATH}`);
+    process.exit(1);
+  }
+
+  const db = new Database(DB_PATH, APPLY ? {} : { readonly: true });
+  if (APPLY) db.pragma('journal_mode = WAL');
+
+  const rows = db
+    .prepare<[], { id: number; result_json: string; body: string | null }>(
+      `SELECT pr.id, pr.result_json, e.body
+       FROM parsed_results pr
+       JOIN emails e ON e.gmail_message_id = pr.gmail_message_id AND e.account_id = pr.account_id
+       WHERE pr.kind = 'vessel'`
+    )
+    .all();
+
+  let patched = 0;
+  let skipped = 0;
+
+  for (const row of rows) {
+    let items: Array<Record<string, unknown>>;
+    try {
+      items = JSON.parse(row.result_json);
+    } catch {
+      continue;
+    }
+    if (!Array.isArray(items)) continue;
+
+    let changed = false;
+    const updated = items.map((item) => {
+      if (item.lastCargoes != null) {
+        skipped++;
+        return item;
+      }
+      const extracted = extractLastCargoesFromBody(row.body ?? '');
+      if (!extracted) return item;
+      changed = true;
+      patched++;
+      return { ...item, lastCargoes: extracted };
+    });
+
+    if (changed) {
+      console.log(`  row ${row.id}: patched ${items.filter((_, i) => updated[i].lastCargoes !== items[i].lastCargoes).length} item(s)`);
+      if (APPLY) {
+        db.prepare('UPDATE parsed_results SET result_json = ? WHERE id = ?').run(
+          JSON.stringify(updated),
+          row.id
+        );
+      }
+    }
+  }
+
+  console.log(`[backfill-last-cargoes] done — patched=${patched}, skipped=${skipped}${APPLY ? '' : ' (dry run, no writes)'}`);
+}
+
+main();
