+  searchParams,
+}: {
+  searchParams: Promise<{ cost?: string }>;
+}) {
+  const { cost: costStr } = await searchParams;
+  const platformCost = Math.max(0, Number(costStr) || DEFAULT_COST);
+
+  const db = getStore().getDatabase();
+  const summary = getRoiSummary(db, platformCost, 90);
+
+  const fmtUsd = (n: number) =>
+    n === 0
+      ? '$0'
+      : new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n);
+
+  return (
+    <main className="min-h-screen bg-ds-bg py-4 sm:py-8 px-3 sm:px-4">
+      <div className="max-w-3xl mx-auto space-y-6">
+        <div className="flex items-center gap-2">
+          <Link href="/dashboard" className="text-sm text-ds-text-muted hover:text-ds-text transition-colors">
+            ← Dashboard
+          </Link>
+        </div>
+
+        <div>
+          <h1 className="text-xl font-bold text-ds-text">ROI Report</h1>
+          <p className="text-sm text-ds-text-muted">Last 90 days · platform cost ${platformCost}/voyage</p>
+        </div>
+
+        {/* KPI grid */}
+        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
+          {[
+            { label: 'Voyages', value: String(summary.totalVoyages) },
+            { label: 'Total savings', value: fmtUsd(summary.totalSavingsUsd) },
+            { label: 'Avg per voyage', value: fmtUsd(summary.avgSavingsPerVoyage) },
+            {
+              label: 'ROI multiple',
+              value: summary.roiMultiple > 0 ? `${summary.roiMultiple.toFixed(1)}×` : '—',
+            },
+          ].map(({ label, value }) => (
+            <div key={label} className="bg-ds-surface border border-ds-border rounded-ds-lg p-4">
+              <p className="text-xs text-ds-text-muted mb-1">{label}</p>
+              <p className="text-lg font-semibold text-ds-text">{value}</p>
+            </div>
+          ))}
+        </div>
+
+        {summary.totalVoyages === 0 && (
+          <p className="text-sm text-ds-text-muted">
+            No voyage data yet. ROI metrics are recorded when deals are confirmed.
+          </p>
+        )}
+
+        {/* Cohort table */}
+        {summary.cohorts.length > 0 && (
+          <div>
+            <h2 className="text-sm font-semibold text-ds-text-muted uppercase tracking-wide mb-3">
+              Monthly breakdown
+            </h2>
+            <div className="bg-ds-surface border border-ds-border rounded-ds-lg overflow-hidden">
+              <table className="w-full text-sm">
+                <thead>
+                  <tr className="border-b border-ds-border">
+                    <th className="text-left px-4 py-2 text-ds-text-muted font-medium">Month</th>
+                    <th className="text-right px-4 py-2 text-ds-text-muted font-medium">Voyages</th>
+                    <th className="text-right px-4 py-2 text-ds-text-muted font-medium">Total savings</th>
+                    <th className="text-right px-4 py-2 text-ds-text-muted font-medium">Avg</th>
+                  </tr>
+                </thead>
+                <tbody>
+                  {summary.cohorts.map((c) => (
+                    <tr key={c.month} className="border-b border-ds-border last:border-0">
+                      <td className="px-4 py-2 text-ds-text">{c.month}</td>
+                      <td className="px-4 py-2 text-right text-ds-text">{c.voyages}</td>
+                      <td className="px-4 py-2 text-right text-ds-text">{fmtUsd(c.totalSavings)}</td>
+                      <td className="px-4 py-2 text-right text-ds-text">{fmtUsd(c.avgSavings)}</td>
+                    </tr>
+                  ))}
+                </tbody>
+              </table>
+            </div>
+          </div>
+        )}
+
+        <p className="text-xs text-ds-text-muted">
+          Platform cost per voyage used for ROI multiple: ${platformCost}.
+          Adjust via <code className="bg-ds-surface px-1 rounded">?cost=N</code> URL param.
+        </p>
+      </div>
+    </main>
+  );
+}
