+import { getStore } from '@/lib/session-store';
+import { getRoiSummary } from '@/lib/analytics/roi-metrics';
+import Link from 'next/link';
+
+const PLATFORM_COST_PER_VOYAGE_USD = 200;
+const WINDOW_DAYS = 90;
+
+function formatUsd(n: number): string {
+  return n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
+}
+
+export default function RoiReportPage() {
+  const db = getStore().getDatabase();
+  const summary = getRoiSummary(db, PLATFORM_COST_PER_VOYAGE_USD, WINDOW_DAYS);
+
+  return (
+    <main className="min-h-screen bg-ds-bg py-4 sm:py-8 px-3 sm:px-4">
+      <div className="max-w-3xl mx-auto space-y-6">
+        <div className="flex items-center justify-between">
+          <Link href="/dashboard" className="text-sm text-ds-text-muted hover:text-ds-text transition-colors">
+            ← Dashboard
+          </Link>
+        </div>
+
+        <div>
+          <h1 className="text-xl font-bold text-ds-text">ROI Report</h1>
+          <p className="text-sm text-ds-text-muted mt-1">Last {WINDOW_DAYS} days · platform cost {formatUsd(PLATFORM_COST_PER_VOYAGE_USD)}/voyage</p>
+        </div>
+
+        {/* KPI strip */}
+        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
+          <div className="rounded-ds-md border border-ds-border bg-ds-surface p-4">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide mb-1">Voyages</p>
+            <p className="text-2xl font-bold text-ds-text">{summary.totalVoyages}</p>
+          </div>
+          <div className="rounded-ds-md border border-ds-border bg-ds-surface p-4">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide mb-1">Total savings</p>
+            <p className="text-2xl font-bold text-ds-text">{formatUsd(summary.totalSavingsUsd)}</p>
+          </div>
+          <div className="rounded-ds-md border border-ds-border bg-ds-surface p-4">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide mb-1">Avg / voyage</p>
+            <p className="text-2xl font-bold text-ds-text">{formatUsd(summary.avgSavingsPerVoyage)}</p>
+          </div>
+          <div className="rounded-ds-md border border-ds-border bg-ds-surface p-4">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide mb-1">ROI multiple</p>
+            <p className="text-2xl font-bold text-ds-text">
+              {summary.totalVoyages === 0 ? '—' : `${summary.roiMultiple.toFixed(1)}×`}
+            </p>
+          </div>
+        </div>
+
+        {/* Empty state */}
+        {summary.totalVoyages === 0 && (
+          <div className="rounded-ds-md border border-ds-border bg-ds-surface p-8 text-center">
+            <p className="text-ds-text-muted text-sm">No voyage data in the last {WINDOW_DAYS} days.</p>
+            <p className="text-xs text-ds-text-subtle mt-1">ROI metrics are recorded when deals close. Run the seed script to populate demo data.</p>
+          </div>
+        )}
+
+        {/* Cohort breakdown */}
+        {summary.cohorts.length > 0 && (
+          <div className="rounded-ds-md border border-ds-border bg-ds-surface overflow-hidden">
+            <div className="px-4 py-3 border-b border-ds-border">
+              <h2 className="text-sm font-semibold text-ds-text">Monthly cohorts</h2>
+            </div>
+            <table className="w-full text-sm">
+              <thead>
+                <tr className="border-b border-ds-border bg-ds-surface-muted">
+                  <th className="text-left px-4 py-2 text-xs text-ds-text-muted font-medium">Month</th>
+                  <th className="text-right px-4 py-2 text-xs text-ds-text-muted font-medium">Voyages</th>
+                  <th className="text-right px-4 py-2 text-xs text-ds-text-muted font-medium">Total savings</th>
+                  <th className="text-right px-4 py-2 text-xs text-ds-text-muted font-medium">Avg / voyage</th>
+                </tr>
+              </thead>
+              <tbody className="divide-y divide-ds-border">
+                {summary.cohorts.map((cohort) => (
+                  <tr key={cohort.month}>
+                    <td className="px-4 py-2 text-ds-text font-mono">{cohort.month}</td>
+                    <td className="px-4 py-2 text-right text-ds-text">{cohort.voyages}</td>
+                    <td className="px-4 py-2 text-right text-ds-text">{formatUsd(cohort.totalSavings)}</td>
+                    <td className="px-4 py-2 text-right text-ds-text">{formatUsd(cohort.avgSavings)}</td>
+                  </tr>
+                ))}
+              </tbody>
+            </table>
+          </div>
+        )}
+      </div>
+    </main>
+  );
+}
