-    if (!f) {
-      transition('idle');
-      return;
-    }
-    try {
-      const fd = new FormData();
-      fd.append('audio', blob, 'voice.webm');
-      const tr = await f(transcribeUrl, { method: 'POST', body: fd });
-      const trJson = (await tr.json().catch(() => null)) as { text?: string } | null;
