+++ b/lib/vessel/passport.ts
@@ -0,0 +1,81 @@
+import type { ParsedVessel } from '@/lib/types';
+import { fetchPscHistory } from '@/lib/knowledge/sources/psc/psc-adapter';
+
+const IACS_TERMS = [
+  'abs', 'american bureau',
+  'bv', 'bureau veritas',
+  'ccs', 'china classification',
+  'dnv', 'det norske',
+  'gl', 'germanischer lloyd',
+  'irs', 'indian register',
+  'kr', 'korean register',
+  'lr', "lloyd's register", 'lloyds register',
+  'nk', 'nippon kaiji', 'classnk',
+  'rina',
+  'rs', 'russian maritime',
+];
+
+const IG_TERMS = [
+  'gard',
+  'west of england',
+  'standard',
+  'britannia',
+  'north p',
+  'skuld',
+  'swedish',
+  'uk p&i', 'uk club',
+  'american club',
+  'japan p&i',
+  'london steam', 'steamship',
+];
+
+export interface VesselPassport {
+  flag: string | null;
+  classSociety: string | null;
+  pandi: string | null;
+  restrictions: string[];
+  lastCargoes: string | null;
+  /** null = classSociety not available; true/false = registry check result */
+  isIacsClass: boolean | null;
+  /** null = pandi not available; true/false = registry check result */
+  isIgPandi: boolean | null;
+  pscInspections: number;
+  pscDetentions: number;
+  pscDeficiencies: number;
+  /** Comma-separated PSC authority names that issued records */
+  pscAuthority: string | null;
+  /** Sanctions check not available (no live sync source) */
+  sanctionsOmitted: true;
+  /** Shadow-fleet check not available (no live sync source) */
+  shadowFleetOmitted: true;
+}
+
+function checkRegistry(value: string | null, terms: string[]): boolean | null {
+  if (!value) return null;
+  const lower = value.toLowerCase();
+  return terms.some(t => lower.includes(t));
+}
+
+export async function buildVesselPassport(vessel: ParsedVessel): Promise<VesselPassport> {
+  const records = vessel.imo ? await fetchPscHistory(vessel.imo) : [];
+
+  const detentions = records.filter(r => r.detained).length;
+  const deficiencies = records.reduce((sum, r) => sum + r.deficiencies, 0);
+  const authorities = [...new Set(records.map(r => r.authority))];
+
+  return {
+    flag: vessel.flag ?? null,
+    classSociety: vessel.classSociety ?? null,
+    pandi: vessel.pandi ?? null,
+    restrictions: vessel.restrictions ?? [],
+    lastCargoes: vessel.lastCargoes ?? null,
+    isIacsClass: checkRegistry(vessel.classSociety ?? null, IACS_TERMS),
+    isIgPandi: checkRegistry(vessel.pandi ?? null, IG_TERMS),
+    pscInspections: records.length,
+    pscDetentions: detentions,
+    pscDeficiencies: deficiencies,
+    pscAuthority: authorities.length > 0 ? authorities.join(', ') : null,
+    sanctionsOmitted: true,
+    shadowFleetOmitted: true,
+  };
+}
diff --git a/scripts/backfill-lastcargoes.ts b/scripts/backfill-lastcargoes.ts
new file mode 100644
index 00000000..25a85139
--- /dev/null
+++ b/scripts/backfill-lastcargoes.ts
@@ -0,0 +1,94 @@
+#!/usr/bin/env tsx
+/**
+ * Idempotent backfill: apply regex lastCargoes extraction to sessions
+ * where the LLM returned null for that field.
+ *
+ * Reads sessions from SESSIONS_DB_PATH (defaults to data/sessions.db).
+ * Only updates vessels where lastCargoes is currently null.
+ * Safe to run multiple times.
+ *
+ * Usage:
+ *   npx tsx scripts/backfill-lastcargoes.ts
+ *   npx tsx scripts/backfill-lastcargoes.ts --dry-run
+ */
+
+import Database from 'better-sqlite3';
+import * as path from 'path';
+import { extractLastCargoesFromBody } from '../lib/parsing/lastcargoes-fallback';
+import type { ParsedVessel, Email } from '../lib/types';
+
+const DRY_RUN = process.argv.includes('--dry-run');
+
+const dbPath =
+  process.env.SESSIONS_DB_PATH ?? path.join(process.cwd(), 'data', 'sessions.db');
+
+const db = new Database(dbPath, { readonly: false });
+
+interface SessionRow {
+  id: string;
+  data: string;
+}
+
+interface SessionBlob {
+  emails?: Email[];
+  parsedVessels?: ParsedVessel[];
+  [key: string]: unknown;
+}
+
+const rows = db.prepare('SELECT id, data FROM sessions').all() as SessionRow[];
+
+let totalSessions = 0;
+let updatedSessions = 0;
+let totalVessels = 0;
+let updatedVessels = 0;
+
+for (const row of rows) {
+  totalSessions++;
+  let blob: SessionBlob;
+  try {
+    blob = JSON.parse(row.data) as SessionBlob;
+  } catch {
+    console.warn(`[skip] session ${row.id}: invalid JSON`);
+    continue;
+  }
+
+  const vessels = blob.parsedVessels ?? [];
+  const emails = blob.emails ?? [];
+
+  let changed = false;
+
+  for (const vessel of vessels) {
+    totalVessels++;
+    if (vessel.lastCargoes != null) continue;
+
+    const email = emails.find((e) => e.id === vessel.emailId);
+    if (!email?.body) continue;
+
+    const extracted = extractLastCargoesFromBody(email.body);
+    if (!extracted) continue;
+
+    vessel.lastCargoes = extracted;
+    changed = true;
+    updatedVessels++;
+    console.log(
+      `  [fill] session=${row.id} vessel="${vessel.vesselName ?? '?'}" lc="${extracted}"`,
+    );
+  }
+
+  if (changed && !DRY_RUN) {
+    db.prepare('UPDATE sessions SET data = ? WHERE id = ?').run(
+      JSON.stringify(blob),
+      row.id,
+    );
+    updatedSessions++;
+  } else if (changed && DRY_RUN) {
+    updatedSessions++;
+  }
+}
+
+const prefix = DRY_RUN ? '[DRY RUN] ' : '';
+console.log(
+  `${prefix}Done: ${updatedVessels} vessels updated across ${updatedSessions}/${totalSessions} sessions`,
+);
+
+db.close();
